#include <stdio.h>
int main(void){int r1,c1,r2,c2,a[20][20],b[20][20],p[20][20]={0};scanf("%d%d",&r1,&c1);for(int i=0;i<r1;i++)for(int j=0;j<c1;j++)scanf("%d",&a[i][j]);scanf("%d%d",&r2,&c2);for(int i=0;i<r2;i++)for(int j=0;j<c2;j++)scanf("%d",&b[i][j]);if(c1!=r2){puts("Invalid dimensions");return 0;}for(int i=0;i<r1;i++)for(int j=0;j<c2;j++)for(int k=0;k<c1;k++)p[i][j]+=a[i][k]*b[k][j];for(int i=0;i<r1;i++){for(int j=0;j<c2;j++)printf("%d%c",p[i][j],j==c2-1?'\n':' ');}return 0;}
